import{Helper}from"../Helper";export class Plan{is_block_features=true;is_block_features_monthly=true;is_require_subscription=true;is_success_manager=false;support_email="";support_forum="";support_phone="";support_skype="";trial_period=0;constructor(object=null){if(null==object){return}for(const p in object){if(object.hasOwnProperty(p)){this[p]=object[p]}}}hasAnySupport(){return this.hasEmailSupport()||this.hasForumSupport()||this.hasPhoneSupport()||this.hasSkypeSupport()||this.hasSuccessManagerSupport()}hasEmailSupport(){return Helper.isNonEmptyString(this.support_email)}hasForumSupport(){return Helper.isNonEmptyString(this.support_forum)}hasKnowledgeBaseSupport(){return Helper.isNonEmptyString(this.support_kb)}hasPhoneSupport(){return Helper.isNonEmptyString(this.support_phone)}hasSkypeSupport(){return Helper.isNonEmptyString(this.support_skype)}hasSuccessManagerSupport(){return true==this.is_success_manager}hasTrial(){return Helper.isNumeric(this.trial_period)&&this.trial_period>0}isBlockingMonthly(){return true==this.is_block_features_monthly}isBlockingAnnually(){return true==this.is_block_features}requiresSubscription(){return this.is_require_subscription}}